// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface TokenTool {
    function owner() external view returns (address);
    function multipleBotlistAddress(address[] calldata accounts, bool excluded) external;
    function _isBlacklisted(address) external view returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x3c6C6d32609d253d54951dB187DAEc272b1d848a;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we're interacting with an already deployed contract
        // We'll need to get the owner address first
        address owner = TokenTool(TARGET).owner();
        vm.label(owner, "Contract Owner");
        vm.label(TARGET, "TokenTool Contract");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        // Step 1: Get the owner address
        address owner = TokenTool(TARGET).owner();

        // Step 2: Impersonate the owner and call multipleBotlistAddress
        vm.startPrank(owner);

        // Create array with attacker address
        address[] memory addresses = new address[](1);
        addresses[0] = attacker;

        // Call to blacklist the attacker (excluded = true means blacklisted)
        TokenTool(TARGET).multipleBotlistAddress(addresses, true);

        vm.stopPrank();

        // Step 3: Verify the blacklist status
        bool isBlacklisted = TokenTool(TARGET)._isBlacklisted(attacker);
        require(isBlacklisted, "Attacker should be blacklisted");
        assertEq(isBlacklisted, true, "Logic Exploit Failed: State not tampered");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

